scripts.check:undef:
node -e "
const {execFileSync} = require('node:child_process');
const fs = require('node:fs');
// A GATE THAT CANNOT FAIL OPEN. The previous form was
//   tsc -p tsconfig.undef.json | grep TS2304 && ... || echo 'no undeclared names'
// which reports success when tsc never ran at all -- a missing config, a broken
// install, a CI image without typescript. That is exactly how a rip-out left ten
// dangling references behind a green check.
if (!fs.existsSync('tsconfig.undef.json')) {
  console.error('check:undef: tsconfig.undef.json is missing. The gate cannot run.');
  process.exit(2);
}
let out = '';
try {
  out = execFileSync('npx', ['--no-install','tsc','-p','tsconfig.undef.json'], {encoding:'utf8'});
} catch (e) {
  if (e.status === undefined) {
    console.error('check:undef: tsc could not be executed:', e.message);
    process.exit(2);
  }
  out = (e.stdout || '') + (e.stderr || '');
}
const hits = out.split('\n').filter((l) => l.includes('TS2304'));
if (hits.length) {
  for (const h of hits) console.error(h);
  console.error('UNDECLARED NAMES FOUND (' + hits.length + ')');
  process.exit(1);
}
console.log('no undeclared names');
"
